"""The final-evaluation notebook (generated by make_final_eval_notebook.py)."""

import ast
import gzip
import json
from pathlib import Path

from training.notebooks.make_final_eval_notebook import NOTEBOOK, render

REPORTS = Path(__file__).resolve().parents[2] / "evaluation" / "reports"


def cells() -> list[dict]:
    return json.loads(NOTEBOOK.read_text(encoding="utf-8"))["cells"]


def cell(prefix: str) -> str:
    (match,) = ["".join(c["source"]) for c in cells() if "".join(c["source"]).startswith(prefix)]
    return match


def test_committed_notebook_matches_its_generator() -> None:
    expected = render()
    assert NOTEBOOK.read_text(encoding="utf-8") == expected, (
        "run: python training/notebooks/make_final_eval_notebook.py "
        "(also after changing vigraph_qlora_windows.ipynb's setup cells)"
    )


def test_code_cells_parse_and_outputs_are_cleared() -> None:
    for c in cells():
        if c["cell_type"] == "code":
            ast.parse("".join(c["source"]))
            assert c["outputs"] == [] and c["execution_count"] is None


def test_sections_and_final_settings() -> None:
    texts = ["".join(c["source"]) for c in cells() if c["cell_type"] == "markdown"]
    headings = [text.split("\n")[0] for text in texts]
    settings = {}
    exec(cell("# ---- Settings"), settings)

    assert [h for h in headings if h.startswith("## ")] == [
        "## 1. Setup",
        "## 2. Dataset — check the one the main notebook built",
        "## A. Greedy decoding — all 500 test samples",
        "## B. Sampling — 3 seeds per model",
    ]
    assert (settings["IMAGE_MAX_SIDE"], settings["MAX_NEW_TOKENS"]) == (896, 2048)
    assert settings["RUNAWAY_GUARD"] is True and settings["SEEDS"] == [0, 1, 2]
    assert settings["SEED_LIMIT"] is None and settings["RUN_NAME"] == "qwen3vl-2b-qlora-a6000-v1"
    assert "F:\\" not in NOTEBOOK.read_text(encoding="utf-8")


def test_runs_use_the_adapter_guard_and_seeds() -> None:
    helpers, qlora, zeroshot, seeds = cell("# A.1"), cell("# A.2"), cell("# A.3"), cell("# B.2")

    assert 'VLM.append("--runaway-guard")' in helpers
    assert '"--max-new-tokens", MAX_NEW_TOKENS' in helpers
    assert '"--adapter", ADAPTER' in qlora and "ADAPTER" not in zeroshot
    assert '"--seed", seed' in seeds and "limit=SEED_LIMIT" in seeds
    assert 'for seed in SEEDS for model in ("qlora", "zeroshot")' in cell("# B.1")


def test_helpers_read_committed_runs() -> None:
    tree = ast.parse(cell("# A.1"))
    wanted = {"finished", "predictions", "by_level"}
    functions = [n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name in wanted]
    namespace = {
        "json": json,
        "gzip": gzip,
        "TEST_SIZE": 500,
        "read_json": lambda path: json.loads(Path(path).read_text(encoding="utf-8")),
    }
    exec(compile(ast.Module(functions, []), "helpers", "exec"), namespace)
    guarded = REPORTS / "qwen3vl-2b-qlora-a6000-v1-px896-guard-s0"

    assert namespace["finished"](guarded, 112) and not namespace["finished"](guarded)
    assert namespace["by_level"](guarded)[4] == (28, 0, 10, 10)  # n, cut off, guard stops, failed
